window.DGNL_DE_MON["l8"] = {"id": "l8", "ten": "Đề thi thử số 8", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "Chọn câu đúng chính tả", "choices": ["Khoản tiền này mẹ để dành cho tôi ôn thi đại học.", "Nếu không học bài, xác xuất để đạt điểm cao là rất thấp.", "Không ai châm trước cho một bài làm cẩu thả.", "Càng làm nhiều đề, em càng được cọ sát với những dạng câu hỏi khác nhau."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu không chứa từ mượn phương Tây", "choices": ["Tấm áp phích chứa nội dung châm biếm đã được gỡ ngay trong hôm đó.", "Một ki ốt bán báo đã được mở cạnh nhà ga.", "Sự phát triển của công nghệ yêu cầu con người phải có khả năng thích nghi.", "Cuộc đối thoại giữa Lan và sếp có vẻ đã không đi đến thoả thuận tốt đẹp."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu chứa yếu tố “hoạ” mang nét nghĩa không giống những phương án còn lại.", "choices": ["Vài người chỉ khen, phụ hoạ theo ý kiến của người đứng đầu mà không kiểm chứng.", "Cơn bão như một tai hoạ giáng xuống ngôi làng.", "Vu oan giá hoạ cho người khác là hành vi đáng trách.", "Tiếng hát thảm hoạ ấy đã phá vỡ sự yên bình của khu xóm."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Hôm nay, chúng ta thành kính tưởng niệm ___ anh hùng đã ngã xuống vì độc lập của Tổ quốc.”<br>Chọn từ phù hợp nhất để điền vào chỗ trống", "choices": ["các", "toàn bộ", "tất cả", "một vài"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu sau mắc lỗi ngữ pháp. Chọn phương án sửa phù hợp nhất.<br><i>“Qua việc tìm hiểu những tư liệu lịch sử và lời kể của các nhân chứng đã cho thấy rõ sự hi sinh to lớn của những con người bình dị trong cuộc chiến tranh bảo vệ Tổ quốc.”</i>", "choices": ["Tư liệu lịch sử và lời kể của các nhân chứng đã cho thấy rõ sự hi sinh to lớn của những con người bình dị trong cuộc chiến tranh bảo vệ Tổ quốc.", "Việc tìm hiểu những tư liệu lịch sử và lời kể của các nhân chứng đã cho thấy rõ sự hi sinh to lớn của những con người bình dị trong cuộc chiến tranh bảo vệ Tổ quốc.", "Việc tìm hiểu những tư liệu lịch sử và lời kể của các nhân chứng, cho thấy rõ sự hi sinh to lớn của những con người bình dị trong cuộc chiến tranh bảo vệ Tổ quốc.", "Qua việc tìm hiểu những tư liệu lịch sử và lời kể của các nhân chứng, sự hi sinh to lớn của những con người bình dị trong cuộc chiến tranh bảo vệ Tổ quốc."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Nếu như ở đầu thời kì Đổi mới, hình tượng con người trong văn học Việt Nam đã chuyển mạnh từ con người ______ sang con người ______, thì ở giai đoạn tiếp theo, văn học tiếp tục hướng tới việc khám phá con người ở chiều sâu bản thể.<br>(Văn học thời kì Đổi mới - xu hướng vận động, Nguyễn Văn Long)<br>Đâu là phương án phù hợp nhất để điền vào chỗ trống?", "choices": ["cộng đồng – cá thể", "bản năng – lí trí", "toàn diện – nhất phiến", "toàn dân – cá nhân"], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Các ông muốn tiểu thuyết cứ là tiểu thuyết. Tôi và các nhà văn cùng chí hướng nhưng tôi muốn tiểu thuyết là sự thực ở đời.” (Vũ Trọng Phụng)<br>Quan niệm trên phản ánh khuynh hướng sáng tác nào?", "choices": ["Chủ nghĩa lãng mạn", "Chủ nghĩa hiện thực phê phán", "Chủ nghĩa tượng trưng", "Chủ nghĩa cổ điển"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Từ việc đọc bài thơ <i>Mùa xuân nho nhỏ</i>, tác giả Thanh Hải đã mang đến cho tôi bài học về lẽ sống cống hiến.”<br>Câu trên mắc lỗi gì?", "choices": ["Lỗi ngữ pháp", "Sai quy chiếu", "Lỗi mơ hồ", "Lỗi dấu câu"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu chứa thành phần khởi ngữ", "choices": ["Quyển sách này, tôi đọc từ hồi lên năm.", "Vì mẹ nấu cơm, hôm nay, tôi có thời gian dành cho việc soạn lại kệ sách.", "Hoa mai, hoa đào, hoa cúc vạn thọ,... là những loài hoa báo hiệu Tết đến.", "Vấn đề anh nói với tôi lần trước, việc thiếu phòng học, đang chờ giải quyết."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Tuổi tác, chùa chiền, hỏi han, hàn huyên...” là những từ _____<br>Chọn từ thích hợp điền vào chỗ trống", "choices": ["từ ghép chính phụ", "từ ghép đẳng lập", "từ láy bộ phận", "từ láy toàn phần"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ sai chính tả", "choices": ["vùng vằng", "dùng dằng", "đằng đẵng", "vằng vện"], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Buồng riêng, riêng <b>những</b> sụt sùi,/ Nghĩ thân mà lại ngậm ngùi cho thân.” (Truyện Kiều, Nguyễn Du)<br>Từ “những” trong câu trên thuộc loại từ gì?", "choices": ["số từ", "phó từ", "trợ từ", "danh từ"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“<b>Song thân</b> dạy bảo vừa xong,<br>Vân Tiên cùng gã <b>tiểu đồng</b> dời chân.<br>Ra đi tách dặm băng chừng,<br>Gió nam rày đã đưa xuân qua hè”<br>(Lục Vân Tiên, Nguyễn Đình Chiểu)<br>Cụm từ in đậm lần lượt có ý nghĩa là gì?", "choices": ["Cha mẹ - người học trò nhỏ", "Cha mẹ - người hầu trung thành", "Hai bậc trưởng bối – người học trò nhỏ", "Hai bậc trưởng bối – người hầu trung thành"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>“Người quốc sắc, kẻ thiên tài,</i><br><i>Tình trong như đã, mặt ngoài còn e.” </i><br>(Truyện Kiều, Nguyễn Du)<br>Tác dụng nội dung của biện pháp tu từ đối trong câu thơ trên là gì?", "choices": ["Làm nổi bật vẻ đẹp và tài năng đặc biệt của hai nhân vật.", "Gợi sự tương xứng về phẩm chất và sự tương đồng về tình cảm của hai nhân vật", "Gợi tả vẻ đẹp lý tưởng của con người trong quan niệm thẩm mỹ trung đại, làm cho câu thơ đăng đối, hài hoà.", "Làm rõ sự đối lập giữa biểu hiện bên ngoài và tâm trạng bên trong của hai nhân vật."], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Cụm từ “ruột đau chín chiều” trong câu ca dao “Chiều chiều ra đứng ngõ sau/ Trông về quê mẹ ruột đau chín chiều” đã được giải thích theo nhiều cách khác nhau. Có ý kiến cho rằng “chín” gợi liên tưởng đến “chín chữ cù lao”, tức công lao sinh thành dưỡng dục của cha mẹ, nên nỗi đau ở đây là nỗi nhớ ơn cha mẹ. Một cách hiểu khác liên hệ với điển tích Hán học “cửu khúc hồi trường” (ruột quanh co chín khúc) dùng để chỉ nỗi đau khổ, rối bời trong tâm trạng. Tuy nhiên, cũng có quan điểm cho rằng trong cách nói của người Việt, “chín” chỉ số lượng nhiều, không xác định, còn “chiều” mang nghĩa là bề, phía, nên “ruột đau chín chiều” chỉ trạng thái đau đớn, thương nhớ ngổn ngang nhiều bề trong lòng. </i><br>Sự đa dạng trong cách hiểu cụm từ “ruột đau chín chiều” cho thấy đặc trưng gì của ngôn ngữ ca dao?", "choices": ["Ngôn ngữ ca dao mang tính đa nghĩa, giàu sức gợi.", "Ngôn ngữ ca dao chủ yếu vay mượn điển tích, điển cố từ văn học Trung Hoa.", "Ngôn ngữ ca dao sử dụng số từ vừa để chỉ chính xác số lượng sự vật, hiện tượng.", "Ngôn ngữ ca dao giàu tính nhạc, giúp người đọc dễ ghi nhớ và tạo tính truyền cảm."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>(Lược trích đoạn Nhị Khanh dặn dò Trọng Quỳ nên cẩn thận với sự xảo quyệt của Đỗ)</i><br><i>Đỗ bỏ ra trăm vạn đồng tiền để đánh và đòi sinh đánh bằng Nhị Khanh. Trọng Quỳ quen mui vẫn được luôn, chẳng suy nghĩ gì, liền bằng lòng cách ấy. Giấy giao kèo viết xong rồi vừa uống rượu vừa gieo quân. Trọng Quỳ gieo ba lần đều thua cả ba, sắc mặt tái mét; cử tọa cũng đều ngơ ngác buồn rầu hộ.</i><br><i>(Lược trích đoạn Trọng Quỳ an ủi, xin lỗi vợ)</i><br><i>Nàng liệu cơ không thể thoát khỏi, giả vờ nói tử tế rằng:</i><br><i>- Bỏ nghèo theo giàu, thiếp lẽ đâu từ chối. Số giời xếp đặt, há chẳng là tiền định hay sao! Nếu chồng mới không nỡ rẻ bỏ, còn đoái thu đến cái dung nhan tàn tạ này, thiếp xin sửa túi nâng khăn, hết lòng hầu hạ như đã đối với chàng xưa nay. Nhưng xin cho uống một chén rượu, mượn làm một chén tiễn biệt và cho về từ giã các con một chút.</i><br><i>Đỗ cả mừng, rót đầy một chén rượu xà cừ đưa mời nàng uống. Uống xong, nàng về nhà ôm lấy hai con, vỗ vào lưng mà bảo rằng:</i><br><i>- Cha con bạc tình, mẹ đau buồn lắm. Biệt ly là việc thường thiên hạ, một cái chết với mẹ có khó khăn gì. Nhưng mẹ chỉ nghĩ thương các con mà thôi.</i><br><i>Nói xong, lấy đoạn dây tơ thắt cổ mà chết.</i><br>(Trích Người nghĩa phụ Khoái Châu, Truyền kì mạn lục, Nguyễn Dữ, in trong cuốn Văn xuôi tự sự Việt Nam thời trung đại, tập 1, Nguyễn Đăng Na giới thiệu và tuyển soạn, NXB Giáo dục, 1997, tr 242 250)<br>Nhận định nào sau đây không đúng với nội dung đoạn trích trên?", "choices": ["Đoạn trích phê phán thói ăn chơi, cờ bạc của Trọng Quỳ và cho thấy sự nhẹ dạ, thiếu trách nhiệm của nhân vật này trong quan hệ gia đình.", "Nhân vật Nhị Khanh hiện lên là người phụ nữ giàu lòng tự trọng và tình mẫu tử nhưng cô vẫn là nạn nhân của hoàn cảnh.", "Qua việc Nhị Khanh từng khuyên chồng đề phòng Đỗ Tam, đoạn trích cho thấy nàng là người có hiểu biết về cuộc đời, song cuối cùng vẫn bất lực trước hành động của chồng.", "Đoạn trích cho thấy Đỗ Tam là người biết lợi dụng cờ bạc để chiếm đoạt Nhị Khanh, nhưng đồng thời cũng thể hiện tính cách trọng tình nghĩa khi chấp nhận cho nàng về từ biệt con."], "correctIndex": 3, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i><b>“</i></b><i>Từng nghe nói rằng: Người hiền xuất hiện ở đời, thì như ngôi sao sáng trên trời cao. Sao sáng ắt chầu về ngôi Bắc Thần, người hiền ắt làm sứ giả cho thiên tử. Nếu như che mất ánh sáng, giấu đi vẻ đẹp, có tài mà không được đời dùng, thì đó không phải là ý trời sinh ra người hiền vậy.”</i> (Chiếu cầu hiền, Ngô Thì Nhậm)<br>Đâu là nhận định <b>không</b> đúng về đoạn trích trên?", "choices": ["Đoạn trích sử dụng hình ảnh so sánh giữa người hiền và sao sáng để làm nổi bật vai trò của hiền tài đối với đất nước.", "Đoạn trích thể hện quan niệm rằng người hiền khi xuất hiện ở đời nên đem tài năng phục vụ triều đình và thiên tử.", "Đoạn trích khẳng định việc người hiền ẩn mình, không tham gia chính sự là phù hợp với ý trời và đạo lý.", "Đoạn trích nhấn mạnh rằng người có tài mà không được sử dụng là điều trái với lẽ tự nhiên."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>“Cúng mẹ và cơm nước xong, mấy chị em, chú cháu thu xếp đồ đạc dời nhà. Chị Chiến ra đứng giữa sân, kéo cái khăn trên cổ xuống, cũng xắn tay áo để lộ hai bắp tay tròn vo sạm đỏ màu cháy nắng, rồi đang cả thân người to và chắc nịch của mình nhấc bổng một đầu bàn thờ má lên. Việt ghé vào một đầu. Nào, đưa má sang ở tạm bên nhà chú, chúng con đi đánh giặc trả thù cho ba má, đến chừng nước nhà độc lập con lại đưa má về. Việt khiêng trước. Chị Chiến khiêng bịch bịch phía sau. Nghe tiếng chân chị, Việt thấy thương chị lạ. Lần đầu tiên Việt mới thấy lòng mình rõ như thế. Còn mối thù thằng Mĩ thì có thể rờ thấy được, vì nó đang đè nặng ở trên vai.”</i><br>(Những đứa con trong gia đình, Nguyễn Thi)<br><b>Người kể chuyện trong văn bản trên sử dụng điểm nhìn trần thuật nào?</b>", "choices": ["Điểm nhìn của ngôi thứ nhất.", "Điểm nhìn của ngôi thứ ba toàn tri.", "Điểm nhìn của ngôi thứ ba hạn tri.", "Điểm nhìn của ngôi thứ hai"], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“Bên thành quách ta ra tay tàn phá.<br>Giữa hoang loạn của lâu đài, đình tạ,<br>Ta thản nhiên, đi trở lại núi rừng.<br>Một mặt trời đẫm máu xuống sau lưng.”<br>(Bài ca man rợ, Đinh Hùng)<br>Hình ảnh “mặt trời đẫm máu” trong câu thơ trên có thể xem là một yếu tố ______ vì tạo nên một liên tưởng phi thực, phá vỡ logic miêu tả thông thường.<br><b>Chọn phương án chứa từ phù hợp nhất để điền vào chỗ trống</b>", "choices": ["tượng trưng", "siêu thực", "lãng mạn", "cổ điển"], "correctIndex": 1, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Cũng chẳng giàu mà cũng chẳng sang,</i><br><i>Chẳng gầy chẳng béo, chỉ làng nhàng.</i><br><i>Cờ đương dở cuộc không còn nước,</i><br><i>Bạc chửa thâu canh đã chạy làng.</i><br><i>Mở miệng nói ra gàn bát sách,</i><br><i>Mềm môi chén mãi tít cung thang.</i><br><i>Nghĩ mình lại ngán cho mình nhỉ,</i><br><i>Mà cũng bia xanh, cũng bảng vàng.</i><br>(Tự trào, Nguyễn Khuyến)<br>Đối tượng trào phúng trực tiếp trong bài thơ trên là gì?", "choices": ["Chính tác giả với sự tự ý thức về cái tầm thường, dở dang của mình.", "Những kẻ sĩ bất tài nhưng vẫn nuôi mộng công danh trong xã hội cũ.", "Tầng lớp quan lại mang danh học thức nhưng sống vô dụng, bê tha.", "Những người theo đòi khoa cử nhưng không đủ năng lực để thành đạt."], "correctIndex": 0, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "(1) Không có nhiều trải nghiệm chiến tranh nhưng lại sống trong không gian của những tái nhận thức về cuộc chiến ấy, từ cái nhìn của người phụ nữ, những vấn đề mà họ đặt ra trong những Có một đêm như thế (Phạm Thị Minh Thư), Người sót lại của rừng cười (Võ Thị Hảo), Tiếng rừng (Hiền Phương), Đàn sẻ ri bay ngang rừng (Võ Thị Xuân Hà)… chắc chắn là những tiếng nói không thể thiếu trong mọi nhìn nhận về văn học giai đoạn này. Việc nữ nhà văn tập kích vào đề tài chiến tranh đã đồng thời làm được hai việc: đặt thêm một góc nhìn mới về chiến tranh, góc nhìn của người phụ nữ và tái nhận thức người nữ trong bối cảnh của chủ nghĩa nữ quyền dân tộc hóa. Những tiếng nói phụ nữ đã bị câm tiếng trong sự đồng hóa của quyền lực đàn ông, khiến chiến tranh “không có khuôn mặt phụ nữ”. Chỉ khi thoát ra ngoài thời gian và không gian bị chiếm dụng, đặc tuyển ấy, người phụ nữ mới ý thức được về họ, những hi sinh mất mát họ phải gánh chịu. Trong số đó, hiển nhiên nổi bật lên sẽ là những ẩn ức từ bản năng giới, cái thế giới bị triệt tiêu, vùi dập, lấp liếm trong các trưng dụng của nam quyền trong chiến tranh. Không phải ngẫu nhiên mà các vấn đề về tình yêu và tình dục trong những truyện ngắn nhắc đến ở trên, ngay khi xuất hiện, đã gây được hiệu ứng mạnh mẽ nơi bạn đọc.<br>(2) Các nhà văn nữ cũng là người mở đường cho sự xuất hiện của các không gian cá nhân (trong những mối quan hệ gia đình, bạn bè, và với chính bản thân), vừa như một vấn đề tự thân, vừa như một nỗ lực thay thế các không gian xã hội thời chiến tranh (trong những mối quan hệ dân tộc, cộng đồng, đội ngũ) đang dần nhạt nhòa trước đời sống dân sự mới mẻ. Xuất phát từ các trải nghiệm giới và tính dục, đời sống đương đại trong tác phẩm của họ thể hiện những cảm nhận khác lạ, khó tìm thấy trong văn học của nam giới và trong nền văn học bị nam tính chi phối trước đó. Dạ Ngân với Trên mái nhà người phụ nữ, Con chó và vụ li hôn, Y Ban với Bức thư gửi mẹ Âu Cơ, I’m đàn bà, Đoàn Lê với nhóm những sáng tác về xóm Chùa (một hiện hữu văn chương về làng Lủ của tác giả), Trần Thùy Mai với Dòng suối cạn nguồn, Thể Cúc, Phan Thị Vàng Anh với Khi người ta trẻ, Kịch câm, Nguyễn Thị Thu Huệ với Hậu thiên đường, Phù thủy, Võ Thị Xuân Hà với Lúa hát, Nhà có ba chị em… là những sáng tác tiêu biểu từ những nhận thức mới ấy. Sự xen cài giữa màu sắc nữ quyền và nữ tính trong sáng tác của thế hệ các nhà văn nữ này, làm nên sức hấp dẫn riêng có của nó, mời gọi tiếp nhận nhưng đồng thời thách thức các nỗ lực diễn giải. Bởi sự phân biệt giữa “nữ tính” và “nữ quyền” là tương đối phức tạp với những biểu hiện đa dạng các cách tiếp cận và biểu hiện của nữ nhà văn lúc này. Song có một thực tế là, lần đầu tiên được trải nghiệm giới trong sự đa dạng, thoát khỏi sự quy chiếu của nữ quyền dân tộc hóa, nữ nhà văn lại thể hiện trong sáng tác của họ cả quá trình đi tìm thiên tính, thiên chức phụ nữ cùng với quyền bình đẳng nam nữ. Vừa thể hiện “bí ẩn nữ tính” và giải cấu nữ tính, sáng tác của các nhà văn nữ làm nên một hiện trạng khá hỗn độn trong biểu hiện ý thức về giới lúc này.<br>(Trích theo “Trải nghiệm về giới sau Đổi mới nhìn từ văn học nữ”, Đoàn Ánh Dương, Văn nghệ Quân đội, 2017).", "cauHoi": [{"question": "Trong đoạn (1), việc tác giả liệt kê các tác phẩm như <i>Có một đêm như thế, Người sót lại của rừng cười, Tiếng rừng, Đàn sẻ ri bay ngang rừng</i> để làm gì?", "choices": ["Minh họa sự xuất hiện của góc nhìn nữ giới khi nhìn lại chiến tranh.", "Khẳng định vị trí trung tâm của đề tài chiến tranh trong văn học nữ.", "Chứng minh chiến tranh là nguồn cảm hứng phổ biến của văn học.", "So sánh đóng góp của các nhà văn nữ với nhà văn nam."], "correctIndex": 0, "explain": ""}, {"question": "Cụm từ <i>“chiến tranh không có khuôn mặt phụ nữ”</i> trong đoạn (1) có ý nghĩa gì?", "choices": ["Phụ nữ ít tham gia trực tiếp vào chiến tranh nên hình tượng người nữ trong chiến tranh trở nên kém nổi bật hơn người nam.", "Chiến tranh thường được kể lại từ trải nghiệm của nam giới.", "Hình ảnh phụ nữ trong chiến tranh thường bị lãng mạn hóa để phục vụ lý tưởng xã hội.", "Trải nghiệm chiến tranh của phụ nữ từng bị che khuất bởi cách nhìn nam giới."], "correctIndex": 3, "explain": ""}, {"question": "Theo văn bản, sự xuất hiện của không gian cá nhân trong sáng tác của các nhà văn nữ gắn với bối cảnh nào?", "choices": ["Xã hội chuyển từ không gian cộng đồng thời chiến sang đời sống dân sự.", "Sự thay đổi thị hiếu tiếp nhận của độc giả trong thời kì hậu chiến.", "Nhu cầu thể hiện cảm xúc riêng tư của các nhà văn nữ.", "Xu hướng đổi mới đề tài của văn học đương đại."], "correctIndex": 0, "explain": ""}, {"question": "Luận đề của văn bản là gì?", "choices": ["Văn học sau chiến tranh chuyển mạnh sang khai thác đời sống cá nhân hơn là đời sống cộng đồng.", "Sự góp phần mở rộng cách nhìn về chiến tranh và trải nghiệm giới của nhà văn nữ.", "Những tác phẩm của nhà văn nữ thường gắn với đề tài gia đình và tình cảm thời kì mới.", "Văn học nữ đương đại đặt trọng tâm vào vấn đề nữ quyền."], "correctIndex": 1, "explain": ""}, {"question": "Nhận định nào sau đây <b>không</b> phù hợp với nội dung văn bản?", "choices": ["Văn học nữ góp phần bổ sung góc nhìn khác khi nhìn lại chiến tranh.", "Không gian cá nhân trong sáng tác nữ gắn với những biến chuyển của đời sống sau chiến tranh.", "Sáng tác của các nhà văn nữ chủ yếu hướng đến việc khẳng định bản sắc nữ giới trong đời sống riêng tư.", "Sự đan xen giữa nữ tính và nữ quyền khiến việc tiếp nhận tác phẩm có nhiều cách diễn giải."], "correctIndex": 2, "explain": ""}], "khongXaoTron": true}, {"noiDungChung": "<b>An Nam tứ đại khí – biểu tượng của khát vọng và sức mạnh dân tộc</b><br><i>Trong lịch sử văn hóa Việt Nam, cụm từ “An Nam tứ đại khí” (hay “Thiên Nam tứ đại khí”) dùng để chỉ bốn bảo vật nổi tiếng được tạo dựng trong thời Lý - Trần. Bốn bảo vật này gồm tháp Báo Thiên, chuông Quy Điền, tượng Phật chùa Quỳnh Lâm và vạc Phổ Minh. Trong lịch sử, chúng từng được xem như những kỳ quan của đất nước, vừa mang ý nghĩa tôn giáo vừa thể hiện sức mạnh văn hóa và tinh thần độc lập của Đại Việt.</i><br><b>1. Tháp Báo Thiên</b><br>Trong bốn bảo vật của An Nam tứ đại khí, tháp Báo Thiên là công trình được xây dựng sớm nhất. Tháp có tên đầy đủ là Đại Thắng Tư Thiên bảo tháp, được dựng vào năm Đinh Dậu (1057) dưới triều vua Lý Thánh Tông. Theo ghi chép trong Đại Việt sử lược, tháp cao khoảng 20 trượng (gần 70 mét) và gồm 30 tầng, tuy có tài liệu khác cho rằng tháp chỉ có 12 tầng. Đây là một công trình kiến trúc đồ sộ của thời Lý, thể hiện trình độ xây dựng và kỹ thuật kiến trúc cao của người Việt lúc bấy giờ.<br>Tuy nhiên, theo dòng chảy của lịch sử, tháp Báo Thiên nhiều lần bị hư hại do thiên tai. Năm 1258, dưới triều Trần Thánh Tông, một trận bão lớn đã làm đổ phần đỉnh tháp. Sau khi được trùng tu, đến năm 1322 đời Trần Minh Tông, tháp lại bị sét đánh làm sạt mất hai tầng. Đến năm 1406, dưới triều Hồ Hán Thương, phần đỉnh tháp một lần nữa bị đổ dù không có bão lớn. Sau này, khi nhà Minh xâm lược nước ta, quân Minh đã phá tháp để lấy đồng đúc vũ khí. Từ đó, công trình kiến trúc vĩ đại này dần biến mất, chỉ còn lại dấu tích trong sử sách.<br><b>2. Chuông Quy Điền</b><br>Bảo vật thứ hai trong An Nam tứ đại khí là chuông Quy Điền, được đúc vào năm 1080 dưới triều vua Lý Nhân Tông, trong dịp sửa lại chùa Diên Hựu (tức chùa Một Cột ngày nay). Để đúc quả chuông khổng lồ này, triều đình đã sử dụng tới 7,3 tấn đồng, cho thấy quy mô và tầm vóc đặc biệt của công trình.<br>Theo truyền thuyết, khi chuông được đúc xong, dù có kích thước lớn nhưng đánh không kêu. Tuy vậy, vì đây là một vật quý nên triều đình không phá bỏ. Thay vào đó, nhà vua cho đưa chuông ra khu ruộng phía sau chùa. Khu vực này vốn thấp trũng và có nhiều rùa sinh sống nên được gọi là Quy Điền (ruộng rùa). Từ đó, quả chuông được gọi với tên quen thuộc là chuông Quy Điền.<br>Chuông Quy Điền tồn tại trong nhiều thế kỷ như một biểu tượng của sự phồn thịnh và sức mạnh kỹ thuật của Đại Việt. Tuy nhiên, cũng giống như nhiều bảo vật khác trong lịch sử, nó không tránh khỏi số phận bị phá hủy trong thời kỳ chiến tranh. Năm 1426, khi quân Minh bị vây tại Đông Quan, tướng Vương Thông đã cho phá chuông Quy Điền để lấy đồng chế tạo vũ khí. Sự kiện này đánh dấu sự biến mất của một trong những bảo vật nổi tiếng nhất trong lịch sử nước ta.<br><b>3. Tượng Phật chùa Quỳnh Lâm</b><br>Bảo vật thứ ba là tượng Phật khổng lồ tại chùa Quỳnh Lâm, thuộc vùng Đông Triều (Quảng Ninh ngày nay). Chùa Quỳnh Lâm từng là một trung tâm Phật giáo lớn của thời Lý - Trần. Tại đây từng có hai pho tượng Phật nổi tiếng được đúc ở hai thời kỳ khác nhau.<br>Pho tượng được xem là một trong Thiên Nam tứ đại khí nhiều khả năng được đúc vào thời Lý do thiền sư Nguyễn Minh Không thực hiện. Theo truyền thuyết, để có đủ nguyên liệu đúc tượng, sư Minh Không đã sang Trung Quốc và thu gom rất nhiều đồng mang về nước. Pho tượng Phật Di Lặc này cao khoảng 6 trượng (gần 20 mét), một kích thước vô cùng lớn vào thời bấy giờ.<br>Vì pho tượng quá đồ sộ nên người ta phải xây dựng một tòa điện cao khoảng 7 trượng để đặt tượng. Theo lời truyền lại trong dân gian, từ khoảng cách 10 dặm vẫn có thể nhìn thấy mái điện che sát đầu tượng, cho thấy quy mô đồ sộ của công trình.<br>Đến thời Trần, thiền sư Pháp Loa, vị tổ thứ hai của Thiền phái Trúc Lâm, đã cho đúc thêm một pho tượng Phật Di Lặc khác vào năm 1327. Sau khi hoàn thành, tượng được dát vàng với sự đóng góp lớn từ các nhân vật hoàng tộc như Trần Quang Triều và công chúa Thượng Trân. Tuy nhiên, trong thời kỳ nhà Minh xâm lược, chùa Quỳnh Lâm bị phá hủy và pho tượng lớn cũng bị cướp mang đi. Sau này chùa được dựng lại nhưng pho tượng khổng lồ đã không còn tồn tại.<br><b>4. Vạc Phổ Minh</b><br>Bảo vật cuối cùng trong An Nam tứ đại khí là vạc Phổ Minh, được đúc vào năm 1262 dưới triều Trần Thánh Tông. Chiếc vạc này được đặt tại chùa Phổ Minh, nằm gần phủ Thiên Trường (nay thuộc Nam Định), nơi gắn liền với quê hương và khu vực sinh sống của hoàng tộc nhà Trần.<br>Tại chùa Phổ Minh, triều đình cho đúc một chiếc vạc đồng khổng lồ và khắc bài minh lên đó. Theo truyền tụng trong dân gian, miệng vạc rộng và dày đến mức hai người có thể đi lại trên vành vạc. Điều này cho thấy quy mô và độ tinh xảo của công trình.<br>Tuy nhiên, giống như chuông Quy Điền, vạc Phổ Minh cũng bị phá hủy trong thời kỳ nhà Minh xâm lược. Năm 1426, khi bị vây ở Đông Quan, quân Minh đã cho phá chiếc vạc để lấy đồng đúc vũ khí.<br>Mặc dù cả bốn bảo vật của An Nam tứ đại khí đều không còn tồn tại đến ngày nay, nhưng giá trị lịch sử và ý nghĩa văn hóa của chúng vẫn được lưu giữ trong sử sách và ký ức dân tộc. Những công trình này không chỉ phản ánh trình độ kỹ thuật và nghệ thuật cao của người Việt thời Lý - Trần, mà còn thể hiện khát vọng xây dựng một quốc gia độc lập, hùng mạnh và giàu bản sắc văn hóa.", "cauHoi": [{"question": "Thông tin chính của văn bản trên là gì?", "choices": ["Giới thiệu nguồn gốc, đặc điểm và ý nghĩa lịch sử của bốn bảo vật trong An Nam tứ đại khí.", "Tái hiện quá trình hình thành và phát triển của các công trình Phật giáo thời Lý - Trần.", "Phản ánh sự thịnh đạt của triều đại Lý - Trần thông qua các công trình kiến trúc lớn.", "Trình bày những biến cố lịch sử liên quan đến các công trình văn hóa cổ."], "correctIndex": 0, "explain": ""}, {"question": "Từ các chi tiết về sự phá hủy của quân Minh đối với chuông Quy Điền và vạc Phổ Minh, có thể rút ra nhận xét nào<b> phù hợp nhất </b>với nội dung văn bản?", "choices": ["Những công trình kim loại lớn thường trở thành nguồn vật liệu trong bối cảnh chiến tranh.", "Các di sản văn hóa dễ bị tổn thất khi đất nước trải qua biến động lịch sử.", "Những công trình lớn thường bị phá hủy khi quyền lực chính trị thay đổi.", "Giá trị vật chất của các bảo vật khiến chúng trở thành mục tiêu trong chiến tranh."], "correctIndex": 1, "explain": ""}, {"question": "Thái độ của tác giả trong đoạn cuối của văn bản được thể hiện chủ yếu qua điều gì?", "choices": ["Sự tiếc nuối trước những công trình kiến trúc không còn tồn tại.", "Niềm tự hào đối với thành tựu văn hóa của dân tộc trong lịch sử.", "Sự phê phán những biến động lịch sử đã làm mất đi nhiều di sản.", "Mong muốn khôi phục lại những bảo vật đã biến mất theo thời gian."], "correctIndex": 1, "explain": ""}, {"question": "Khi trình bày về tượng Phật chùa Quỳnh Lâm, văn bản đưa vào nhiều chi tiết truyền thuyết và số liệu kích thước. Cách kết hợp này chủ yếu nhằm mục đích gì?", "choices": ["Nhấn mạnh ý nghĩa tâm linh của tượng Phật trong đời sống người Việt.", "Làm rõ quy mô của pho tượng và trí tưởng tượng dân gian về nó.", "Cho thấy nguồn tư liệu lịch sử về công trình còn nhiều khác biệt.", "Nhấn mạnh vai trò của các thiền sư trong việc xây dựng công trình tôn giáo."], "correctIndex": 1, "explain": ""}, {"question": "Đoạn văn “Tuy nhiên, theo dòng chảy của lịch sử,... dấu tích trong sử sách.” trình bày thông tin theo cấu trúc nào?", "choices": ["Trật tự thời gian", "Trật tự không gian", "Phân loại thông tin", "Cấu trúc so sánh đối chiếu"], "correctIndex": 0, "explain": "Đáp án<br><table class=\"bang-de\"><tr><td><b>Câu</b></td><td><b>1</b></td><td><b>2</b></td><td><b>3</b></td><td><b>4</b></td><td><b>5</b></td><td><b>6</b></td><td><b>7</b></td><td><b>8</b></td><td><b>9</b></td><td><b>10</b></td><td><b>11</b></td><td><b>12</b></td><td><b>13</b></td><td><b>14</b></td><td><b>15</b></td></tr><tr><td>ĐA</td><td>A</td><td>C</td><td>A</td><td>C</td><td>B</td><td>A</td><td>B</td><td>B</td><td>A</td><td>B</td><td>D</td><td>C</td><td>B</td><td>B</td><td>A</td></tr><tr><td><b>Câu</b></td><td><b>16</b></td><td><b>17</b></td><td><b>18</b></td><td><b>19</b></td><td><b>20</b></td><td><b>21</b></td><td><b>22</b></td><td><b>23</b></td><td><b>24</b></td><td><b>25</b></td><td><b>26</b></td><td><b>27</b></td><td><b>28</b></td><td><b>29</b></td><td><b>30</b></td></tr><tr><td>ĐA</td><td>D</td><td>C</td><td>C</td><td>B</td><td>A</td><td>A</td><td>D</td><td>A</td><td>B</td><td>C</td><td>A</td><td>B</td><td>B</td><td>B</td><td>A</td></tr></table>"}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>Haven&#x27;t you got anything better to do than hang ______at the shopping center?", "choices": ["in", "on", "over", "out"], "correctIndex": 3, "explain": "<b>Câu 31. Chọn D.</b> Cụm từ <b>Hang out</b>: đi chơi, la cà (tại trung tâm thương mại)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Lisa was cycling to school when she ______ the accident.", "choices": ["saw", "was seeing", "sees", "had seen."], "correctIndex": 0, "explain": "<b>Câu 32.</b> <b>Chọn A.</b> Thì quá khứ đơn (<b>saw</b>) diễn tả một hành động xen vào một hành động khác đang xảy ra trong quá khứ (was cycling)"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Which beaches were the ones that you liked ______ than any others?", "choices": ["most", "least", "more", "fewer."], "correctIndex": 0, "explain": "<b>Câu 33. Chọn A.</b><br>Cấu trúc so sánh hơn: More + danh từ/tính từ + than. Ở đây so sánh mức độ yêu thích giữa các bãi biển."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "He takes the ______ for running the household.", "choices": ["responsibility", "responsible", "responsibly", "responsiveness"], "correctIndex": 0, "explain": "<b>Câu 34.</b> <b>Chọn A.</b> Sau mạo từ &quot;the&quot; cần một danh từ. Cụm từ <b>Take the responsibility for</b>: chịu trách nhiệm cho việc gì."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "______ people have been employed to deal with the backlog of work.", "choices": ["The number of", "A number of", "An amount of", "A great deal of."], "correctIndex": 1, "explain": "<b>Câu 35.</b> <b>Chọn B.</b> <b>A number of + danh từ số nhiều</b>: dùng để chỉ một lượng người/vật đếm được. (An amount of/A great deal of dùng cho danh từ không đếm được)."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 36-40: </b>Mark the letter A, B, C, or D on your answer sheet to indicate the wrong word use/form to each of the following statement.", "cauHoi": [{"question": "<u><b>The</u></b> former president has agreed <b><u>to</u></b> act as <b><u>an</u></b> intermediary between <b><u>a</u></b> government and the rebels.", "choices": ["The", "to", "an", "a."], "correctIndex": 3, "explain": "<b>Câu 36.</b> <b>Chọn D.</b> Sửa &quot;a government&quot; thành <b>the government</b>. Cần mạo từ xác định &quot;the&quot; vì đang nói đến chính phủ cụ thể của quốc gia có phiến quân đó."}, {"question": "<u><b>The</u></b> Vietnamese <b><u>is</u></b> one of the four main <b><u>groups</u></b> of Vietic speakers in Vietnam, the <b><u>others</u></b> being the Mường, Thổ, and Chứt people.", "choices": ["The", "is", "groups", "others."], "correctIndex": 1, "explain": "<b>Câu 37.</b> <b>Chọn B.</b> Sửa &quot;is&quot; thành <b>are</b>. Cụm &quot;The Vietnamese&quot; ở đây chỉ toàn thể người dân/dân tộc Việt Nam (danh từ tập hợp chỉ người) nên chia động từ số nhiều."}, {"question": "She disliked <b><u>the</u></b> president, <b><u>who</u></b> she once described <b><u>as</u></b> <b><u>an</u></b> &#x27;insufferable bore&#x27;.", "choices": ["the", "who", "as", "an."], "correctIndex": 1, "explain": "<b>Câu 38.</b> <b>Chọn B.</b> Sửa &quot;who&quot; thành <b>whom</b>. Đại từ quan hệ đóng vai trò tân ngữ của động từ &quot;described&quot; và đứng sau dấu phẩy phải là &quot;whom&quot;."}, {"question": "<u><b>Sabrina</u></b> opinion <b><u>is</u></b> also quite interesting but <b><u>mine</u></b> seems more feasible <b><u>for</u></b> this campaign.", "choices": ["Sabrina", "is", "mine", "for."], "correctIndex": 0, "explain": "<b>Câu 39.</b> <b>Chọn A.</b> Sửa &quot;Sabrina&quot; thành <b>Sabrina&#x27;s</b>. Cần hình thức sở hữu cách (Ý kiến của Sabrina) để tương ứng với đại từ sở hữu &quot;mine&quot; ở vế sau."}, {"question": "Phoebe often says <b><u>my</u></b> laptop has more features than <b><u>her</u></b> so <b><u>she</u></b> usually borrows <b><u>mine</u></b>.", "choices": ["my", "her", "she", "mine."], "correctIndex": 1, "explain": "<b>Câu 40.</b> <b>Chọn B.</b> Sửa &quot;her&quot; thành <b>hers</b>. Dùng đại từ sở hữu &quot;hers&quot; để thay thế cho cụm &quot;her laptop&quot;, tránh lặp từ."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "&quot;Did you finish your homework?&quot; she asked.", "choices": ["She told me not to finish my homework.", "She asked me to finish my homework.", "She accused me of not finishing my homework.", "She asked if I had finished my homework."], "correctIndex": 3, "explain": "<b>Câu 41.</b> <b>Chọn D.</b> Câu tường thuật dạng câu hỏi Yes/No: lùi thì từ quá khứ đơn sang quá khứ hoàn thành và thêm <b>if/whether</b>."}, {"question": "The match was canceled because of heavy rain.", "choices": ["The match would be canceled unless it rained.", "If it rains, the match will be canceled.", "If it hadn&#x27;t rained heavily, the match wouldn&#x27;t have been canceled.", "If it rained, the match would not be canceled."], "correctIndex": 2, "explain": "<b>Câu 42.</b> <b>Chọn C.</b> Viết lại câu bằng câu điều kiện loại 3 (trái với sự thật trong quá khứ): <b>If + S + had (not) PII, S + would (not) have PII</b>."}, {"question": "No one in the office works harder than John.", "choices": ["John doesn&#x27;t work harder than anyone in the office.", "John works as hard as everyone in the office.", "Everyone works harder than John in the office.", "John is the hardest-working person in the office."], "correctIndex": 3, "explain": "<b>Câu 43.</b> <b>Chọn D.</b> So sánh nhất tương đương: &quot;Không ai làm việc chăm hơn John&quot; = &quot;John là người làm việc chăm nhất&quot;."}, {"question": "Attention! All drivers are required to obey traffic laws to ensure road safety and prevent accidents.", "choices": ["Drivers should obey traffic laws to ensure road safety and prevent accidents.", "Drivers must obey traffic laws to ensure road safety and prevent accidents.", "Drivers may have obeyed traffic law to ensure road safety and prevent accidents.", "Drivers should have obeyed traffic laws to ensure road safety and prevent accidents."], "correctIndex": 1, "explain": "<b>Câu 44.</b> <b>Chọn B.</b> Động từ &quot;required&quot; (bắt buộc) mang nghĩa cưỡng bách, tương đương với trợ động từ <b>must</b>."}, {"question": "The library is unusually quiet today, possibly because of the holiday.", "choices": ["The decline in visitors is unlikely due to the holiday.", "It is possible that the holiday will not affect the number of visitors.", "The holiday may be the reason for the quiet library.", "The decline in visitors is certainly due to the holiday."], "correctIndex": 2, "explain": "<b>Câu 45.</b> <b>Chọn C.</b> Trạng từ &quot;possibly&quot; (có khả năng) tương đương với động từ khuyết thiếu <b>may</b> (diễn tả sự dự đoán không chắc chắn)."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question</b><br><b>1.</b> Domestic abuse, also known as domestic violence or intimate partner violence, is a serious issue that affects people from all walks of life. It is a pattern of behaviors used by one person to gain or maintain power and control over their intimate partner. Abuse can take many different forms, including physical, emotional, sexual, economic, and psychological abuse. It can involve actions or threats that cause fear, harm, or distress to another person.<br><b>2.</b> Many people think of domestic abuse as only physical violence, such as hitting or pushing.<br>However, abuse is not always physical. It can also include verbal and emotional abuse, such as constant criticism, name-calling, or manipulation. Some abusers try to control their partner&#x27;s finances, making it difficult for them to become independent. Others may isolate their partner from family and friends, making it harder for <b><u>them</u></b> to seek help. Threats, intimidation, humiliation, and gaslighting are also common tactics used by abusers.<br><b>3.</b> Domestic violence can happen to anyone regardless of race, age, sexual orientation, religion, sex, or gender identity. Domestic violence affects people of all socioeconomic backgrounds and education levels. Domestic violence occurs in both opposite-sex and same-sex relationships and can happen to intimate partners who are married, living together, dating, or sharing a child.<br><b>4.</b> Domestic violence does not only harm the person being abused, it also has serious <b><u>consequences</u></b> for family members, friends, co-workers, and society as a whole. Children who grow up in violent households are especially vulnerable. They may develop emotional and behavioral issues, struggle in school, or experience anxiety and depression. In many cases, children who witness domestic violence may believe that abuse is a normal part of relationships, increasing their risk of becoming victims or abusers in the future.<br><b>5.</b> The effects of domestic violence extend beyond the home. It can impact workplaces, schools, and entire communities. Victims may have difficulty maintaining employment due to stress or injuries, leading to financial struggles. Domestic violence can also lead to increased healthcare costs and put a strain on legal and social services.<br><b>6.</b> Ending domestic abuse requires education, awareness, and support for victims. It is important for individuals to recognize the signs of abuse and know where to seek help. Many organizations offer hotlines, shelters, counseling, and legal assistance to help victims escape abusive situations and rebuild their lives. Friends, family members, and communities also play a vital role in offering support and breaking the cycle of violence.", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["The different types of abuse in relationships", "The impact of domestic violence on children", "The causes, effects, and solutions to domestic abuse", "The role of society in preventing domestic violence"], "correctIndex": 2, "explain": "<b>Câu 46. Chọn C.</b><br>Bài viết tổng hợp từ định nghĩa, các hình thức bạo lực đến hậu quả và cách giải quyết."}, {"question": "What does the word &quot;<b>them</b>&quot; refer to in paragraph 2?", "choices": ["The abusers", "The finances", "The victims", "The threats."], "correctIndex": 2, "explain": "<b>Câu 47.</b> <b>Chọn C.</b> Từ &quot;them&quot; ở đoạn 2 thay thế cho <b>victims</b> (những người bạn đời bị kiểm soát tài chính)."}, {"question": "In paragraph 3, which of the following is NOT mentioned as a characteristic of domestic violence?", "choices": ["It affects people regardless of gender identity.", "It occurs in both opposite-sex and same-sex relationships.", "It can happen to married, dating, or cohabiting partners.", "It only happens to people with lower education levels."], "correctIndex": 3, "explain": "<b>Câu 48.</b> <b>Chọn D.</b> Đoạn 3 khẳng định bạo lực gia đình xảy ra ở mọi trình độ học vấn (&quot;all education levels&quot;), không chỉ người học vấn thấp."}, {"question": "The closest meaning to the word &quot;<b><u>consequences</u></b>&quot; in paragraph 4 is:", "choices": ["Benefits", "Effects", "Causes", "Reasons."], "correctIndex": 1, "explain": "<b>Câu 49.</b> <b>Chọn B.</b> Từ <b>Consequences</b> đồng nghĩa với <b>Effects</b> (hệ quả/tác động)."}, {"question": "What can be inferred about children who witness domestic violence in paragraph 4?", "choices": ["They may grow up believing that abuse is a normal part of relationships.", "They learn that violence is an unacceptable way to solve problems.", "They are less likely to experience emotional problems.", "They will always become abusers themselves."], "correctIndex": 0, "explain": "<b>Câu 50.</b> <b>Chọn A.</b> Đoạn 4 nêu trẻ em chứng kiến bạo lực có thể coi đó là điều bình thường trong các mối quan hệ sau này."}, {"question": "What is a stated detail in paragraph 5 about the impact of domestic violence?", "choices": ["Domestic violence only affects personal relationships.", "Victims of domestic violence usually recover quickly.", "Domestic violence does not affect workplaces or schools.", "Domestic violence can lead to financial struggles and increased healthcare costs."], "correctIndex": 3, "explain": ""}, {"question": "What is a stated detail in paragraph 6 about ending domestic abuse?", "choices": ["Only victims themselves can break the cyele of violence.", "There are very few organizations available to help victims.", "Education, awareness, and support for victims are needed to stop domestic abuse.", "Victims of domestic abuse rarely need legal assistance."], "correctIndex": 2, "explain": "<b>Câu 52.</b> <b>Chọn C.</b> Dòng đầu đoạn 6 khẳng định việc chấm dứt bạo lực cần sự giáo dục, nhận thức và hỗ trợ nạn nhân."}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.<br><b>1.</b> The greenhouse effect is a process that occurs when gases in Earth&#x27;s atmosphere trap the Sun&#x27;s heat. This process makes Earth much warmer than it would be without an atmosphere. The greenhouse effect is one of the things that makes Earth a comfortable place to live.<br><b>2.</b> As you might expect from the name, the greenhouse effect works.... like a greenhouse! A greenhouse is a building with glass walls and a glass roof. Greenhouses are used to grow plants, such as tomatoes and tropical flowers. A greenhouse stays warm inside, even during the winter. In the daytime, sunlight shines into the greenhouse and warms the plants and air inside. At nighttime, it&#x27;s colder outside, but the greenhouse stays pretty warm inside. <b><u>That</u></b>&#x27;s because the glass walls of the greenhouse trap the Sun&#x27;s heat.<br><b>3.</b> The greenhouse effect works much the same way on Earth. Gases in the atmosphere, such as carbon dioxide, <b><u>trap</u></b> heat similar to the glass roof of a greenhouse. These heat-trapping gases are called greenhouse gases. During the day, the Sun shines through the atmosphere. Earth&#x27;s surface warms up in the sunlight. At night, Earth&#x27;s surface cools, releasing heat back into the air. But some of the heat is trapped by the greenhouse gases in the atmosphere. That&#x27;s what keeps our Earth a warm and cozy 58 degrees Fahrenheit (14 degrees Celsius), on average.<br><b>4.</b> Human activities are changing Earth&#x27;s natural greenhouse effect. Burning fossil fuels like coal and oil puts more carbon dioxide into our atmosphere. NASA has observed increases in the amount of carbon dioxide and some other greenhouse gases in our atmosphere. Too much of these greenhouse gases can cause Earth&#x27;s atmosphere to trap more and more heat. This causes Earth to warm up.<br><b>5.</b> Just like a glass greenhouse, Earth&#x27;s greenhouse is also full of plants! Plants can help to balance the greenhouse effect on Earth. All plants - from giant trees to <b><u>tiny</u></b> phytoplankton in the ocean - take in carbon dioxide and give off oxygen. The ocean also absorbs a lot of excess carbon dioxide in the air. Unfortunately, the increased carbon dioxide in the ocean changes the water, making it more acidic. This is called ocean acidification. More acidic water can be harmful to many ocean creatures, such as certain shellfish and coral. Warming oceans - from too many greenhouse gases in the atmosphere - can also be harmful to these organisms. Warmer waters are the main cause of coral bleaching.", "cauHoi": [{"question": "The best title of the passage can be", "choices": ["The Importance of the Greenhouse Effect", "How the Greenhouse Effect Works", "The Role of Plants in Controlling Carbon Dioxide", "The Causes of Global Warming"], "correctIndex": 1, "explain": "<b>Câu 53.</b> <b>Chọn B.</b> Tiêu đề phù hợp nhất là &quot;Cách thức hoạt động của hiệu ứng nhà kính&quot; vì bài viết giải thích cơ chế giữ nhiệt."}, {"question": "The word &quot;<b><u>that</u></b>&quot; in paragraph 2 refers to", "choices": ["The greenhouse staying warm inside", "The cold temperature outside", "The sunlight shining into the greenhouse", "The plants growing inside the greenhouse."], "correctIndex": 0, "explain": "<b>Câu 54.</b> <b>Chọn A.</b> &quot;That&quot; thay thế cho việc <b>nhà kính giữ ấm được bên trong</b> nhờ các bức tường kính đã nhắc ở câu trước."}, {"question": "In paragraph 3, the author uses the word &quot;<b><u>trap</u></b>&quot; in order to __________", "choices": ["Suggest that the greenhouse effect only happens during the day", "Describe how plants absorb sunlight", "Show that heat is permanently stuck in the air", "Explain how greenhouse gases hold heat in the atmosphere"], "correctIndex": 3, "explain": "<b>Câu 55.</b> <b>Chọn D.</b> Tác giả dùng từ &quot;trap&quot; (bẫy/giữ) để giải thích cách các khí giữ nhiệt lại trong bầu khí quyển."}, {"question": "What can be inferred from paragraph 4 about the role of human activities in climate change?", "choices": ["Human activities have little effect on Earth&#x27;s temperature.", "The amount of carbon dioxide in the atmosphere has remained stable over time.", "Burning fossil fuels increases greenhouse gases, leading to global warming.", "NASA has found that carbon dioxide levels are decreasing."], "correctIndex": 2, "explain": "<b>Câu 56.</b> <b>Chọn C.</b> Đoạn 4 suy luận rằng hoạt động đốt nhiên liệu hóa thạch của con người làm tăng khí thải, gây nóng lên toàn cầu."}, {"question": "The word &quot;<b><u>tiny</u></b>&quot; in paragraph 5 can be replaced by.", "choices": ["Small", "Huge", "Slow", "Weak"], "correctIndex": 0, "explain": "<b>Câu 57.</b> <b>Chọn A.</b> <b>Tiny</b> đồng nghĩa với <b>Small</b> (nhỏ bé)."}, {"question": "In paragraph 5, it is NOT mentioned that", "choices": ["Plants take in carbon dioxide and release oxygen.", "The ocean absorbs excess carbon dioxide.", "Burning fossil fuels helps plants grow faster.", "Increased carbon dioxide in the ocean makes the water more acidic."], "correctIndex": 2, "explain": "<b>Câu 58.</b> <b>Chọn C.</b> Thông tin &quot;đốt nhiên liệu hóa thạch giúp cây lớn nhanh&quot; không hề xuất hiện trong đoạn 5."}, {"question": "It can be inferred from paragraph 5 that", "choices": ["The ocean has no effect on carbon dioxide levels.", "Too much carbon dioxide in the ocean negatively impacts marine life.", "Ocean acidification has no connection to the greenhouse effect.", "Coral reefs benefit from increased levels of carbon dioxide."], "correctIndex": 1, "explain": "<b>Câu 59.</b> <b>Chọn B.</b> Đoạn 5 nêu rõ CO2 làm tăng tính axit của nước biển, gây hại cho sinh vật biển (san hô, loài có vỏ)."}, {"question": "It can be seen in paragraphs 4 and 5 that __________", "choices": ["The ocean absorbs carbon dioxide without any negative consequences.", "The greenhouse effect has no connection to human activities.", "Fossil fuel use has no impact on Earth&#x27;s atmosphere.", "Human activities contribute to climate change, but plants and the ocean help regulate carbon dioxide levels."], "correctIndex": 3, "explain": "<b>Câu 60.</b> <b>Chọn D.</b> Kết hợp đoạn 4 và 5: Con người gây ra biến đổi khí hậu, nhưng thực vật và đại dương đóng vai trò điều hòa CO2."}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Vào năm 1864, hai nhà khoa học người Na Uy là Cato Maximilian Guldberg và Peter Waage đã công bố định luật tác dụng khối lượng, đánh dấu bước tiến lớn trong nghiên cứu về động học hóa học. Theo định luật này, tốc độ của một phản ứng hóa học ở một nhiệt độ xác định tỉ lệ thuận với tích nồng độ các chất phản ứng, mỗi nồng độ được lũy thừa theo hệ số tỉ lượng trong phương trình phản ứng.<br>Xét phản ứng: <span class=\"ct\">aA + bB → cC + dD</span><br>thì tốc độ phản ứng được biểu diễn bởi công thức: <span class=\"ct\">v = k[A]<sup>a</sup>[B]<sup>b</sup></span>; trong đó k là hằng số tốc độ phản ứng và phụ thuộc vào nhiệt độ.<br>Định luật tác dụng khối lượng giúp giải thích cơ chế phản ứng, thiết lập biểu thức tốc độ, và là cơ sở để xây dựng khái niệm cân bằng hóa học động. Khi phản ứng thuận nghịch xảy ra đồng thời với cùng tốc độ, hệ đạt trạng thái cân bằng; khi đó, tỉ lệ giữa tích nồng độ sản phầm và tích nồng độ chất phản ứng (mỗi nồng độ lũy thừa theo hệ số tỉ lượng) là một hằng số gọi là hằng số cân bằng <span class=\"ct\">k<sub>c</sub></span>.<br>Ngày nay, định luật này được ứng dụng rộng rãi trong nhiều lĩnh vực, từ công nghiệp hóa chất (tối ưu tốc độ phản ứng) đến môi trường (dự đoán tốc độ phân hủy chất ô nhiễm), y học (nghiên cứu phản ứng sinh hóa trong cơ thể).", "cauHoi": [{"question": "Yếu tố nào <b>không</b> ảnh hưởng trực tiếp đến tốc độ phản ứng?", "choices": ["Nồng độ chất phản ứng.", "Hằng số tốc độ k .", "Nồng độ chất sản phẩm.", "Nhiệt độ."], "correctIndex": 2, "explain": "<b>Đáp án: C</b>"}, {"question": "Xét phản ứng: <span class=\"ct\">aA + bB → cC + dD</span>, khi tăng nồng độ chất A lên 2 lần, giữ nguyên nồng độ chất B thì tốc độ phản ứng tăng lên 4 lần; khi tăng nồng độ chất B lên 2 lần và giữ nguyên nồng độ chất A thì tốc độ phản ứng tăng lên 2 lần. Chọn phát biểu đúng:", "choices": ["<span class=\"ct\">a = 2,b = 1</span>.", "<span class=\"ct\">a = 1,b = 2</span>.", "<span class=\"ct\">a = 2,b = 2</span>.", "<span class=\"ct\">a = 1,b = 1</span>."], "correctIndex": 0, "explain": "<b>Đáp án: A</b><br><b>Hướng dẫn giải:</b><br><table class=\"bang-de\"><tr><td>\\(v = k\\lbrack A\\rbrack^{2} \\cdot \\lbrack\\text{ }B\\rbrack^{b}\\) \\(v^{&#x27;} = k\\lbrack 2A\\rbrack^{2} \\cdot \\lbrack B\\rbrack^{b} = 2^{2} \\cdot k \\cdot \\lbrack A\\rbrack^{2} \\cdot \\lbrack B\\rbrack^{b} = 2^{2} \\cdot v\\)<br>\\[4v = 2^{2}.v \\Rightarrow 4 = 2^{2} \\Rightarrow a = 2\\]</td><td>\\(v^{&#x27;&#x27;} = k\\lbrack A\\rbrack^{2} \\cdot \\lbrack 2B\\rbrack^{b} = 2^{b} \\cdot k \\cdot \\lbrack A\\rbrack^{2} \\cdot \\lbrack B\\rbrack^{b} = 2^{b} \\cdot v\\) <span class=\"ct\">2v = 2<sup>b</sup>·v ⇒ 2 = 2<sup>b</sup> ⇒ b = 1</span></td></tr></table>"}, {"question": "Xét phản ứng ở trạng thái cân bằng: <span class=\"ct\">2SO<sub>2</sub> + O<sub>2</sub> ⇌ 2SO<sub>3</sub></span>. Hằng số cân bằng được biểu diễn:", "choices": ["\\(\\mathrm{k}_{\\mathrm{c}}=\\frac{\\left[\\mathrm{SO}_3\\right]}{\\left[\\mathrm{SO}_2\\right] \\cdot\\left[\\mathrm{O}_2\\right]}\\)", "\\(\\mathrm{k}_{\\mathrm{c}}=\\frac{\\left[\\mathrm{SO}_3\\right]^2}{\\left[\\mathrm{SO}_2\\right]^2 \\cdot\\left[\\mathrm{O}_2\\right]}\\)", "\\(\\mathrm{k}_{\\mathrm{c}}=\\frac{\\left[\\mathrm{SO}_2\\right] \\cdot\\left[\\mathrm{O}_2\\right]}{\\left[\\mathrm{SO}_3\\right]}\\)", "\\(\\mathrm{k}_{\\mathrm{c}}=\\frac{\\left[\\mathrm{SO}_2\\right]^2 \\cdot\\left[\\mathrm{O}_2\\right]}{\\left[\\mathrm{SO}_3\\right]^2}\\)"], "correctIndex": 1, "explain": "<b>Đáp án: B</b><br><b>Hướng dẫn giải: </b>Theo đề bài: Khi phản ứng thuận nghịch xảy ra đồng thời với cùng tốc độ, hệ đạt trạng thái cân bằng; khi đó, tỉ lệ giữa tích nồng độ sản phầm và tích nồng độ chất phản ứng (mỗi nồng độ lũy thừa theo hệ số tỉ lượng) là một hằng số gọi là hằng số cân bằng <span class=\"ct\">k<sub>c</sub></span>."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br><img class=\"anh-de\" src=\"data/anh/l8/537c5cd1dcba4650.png\" alt=\"\" style=\"width:207px;height:153px\">Trong các <b>nhà máy luyện kim và sản xuất thép tấm</b>, các tấm kim loại sau khi cán phải có <b>độ dày rất chính xác</b> (sai số chỉ vài phần trăm milimét). Nếu tấm kim loại <b>quá dày</b> sẽ tốn nguyên liệu và khó gia công tiếp; nếu <b>quá mỏng</b> sẽ làm giảm độ bền sản phẩm. Vì vậy, nhiều dây chuyền cán hiện đại sử dụng <b>thiết bị đo độ dày bằng nguồn phóng xạ β⁻</b> để kiểm tra liên tục độ dày của lá kim loại trong khi đang cán và <b>tự động điều chỉnh khoảng cách giữa hai con lăn</b>.<br>Trong hệ thống này, <b>nguồn phóng xạ β⁻ đặt dưới tấm vật liệu</b> phát ra các hạt β⁻ đi xuyên qua lá kim loại đang được cán. Phía trên tấm vật liệu là <b>đầu thu bức xạ</b> dùng để đo cường độ bức xạ truyền qua. Nếu tấm kim loại <b>dày lên</b>, nhiều hạt β⁻ bị hấp thụ nên <b>cường độ bức xạ tới đầu thu giảm</b>; nếu tấm <b>mỏng đi</b>, cường độ bức xạ tăng. Tín hiệu từ đầu thu được đưa tới <b>bộ điều khiển</b>, bộ này sẽ điều chỉnh vị trí các con lăn để giữ cho độ dày tấm kim loại luôn ổn định.<br>Cường độ bức xạ β⁻ sau khi đi qua lớp vật liệu dày <span class=\"ct\">x</span> được xác định bởi công thức<br><span class=\"ct\">I = I<sub>0</sub>e<sup>−μx</sup></span><br>trong đó<br><span class=\"ct\">I<sub>0</sub></span> là cường độ bức xạ ban đầu từ nguồn, số hạt bức xạ đếm được trong một giây, đơn vị (<span class=\"ct\">s<sup>−1</sup></span>)<br><span class=\"ct\">I</span> là cường độ bức xạ tới đầu thu, đơn vị (<span class=\"ct\">s<sup>−1</sup></span>),<br><span class=\"ct\">μ</span> là hệ số hấp thụ bức xạ của vật liệu <span class=\"ct\">(mm<sup>−1</sup>)</span>,<br><span class=\"ct\">x</span> là độ dày của lá vật liệu (mm).", "cauHoi": [{"question": "Khi đầu thu nhận được tín hiệu bức xạ lớn hơn giá trị chuẩn, điều đó cho thấy", "choices": ["vật liệu dày hơn chuẩn", "vật liệu mỏng hơn chuẩn", "nguồn phóng xạ yếu đi", "đầu thu bị hỏng"], "correctIndex": 1, "explain": "<b>Câu 106. Chọn B</b><br>Theo cơ chế hệ thống, khi tia β⁻ đi qua vật liệu:<br>Vật liệu càng dày → hấp thụ nhiều tia → cường độ tới đầu thu giảm.<br>Vật liệu càng mỏng → hấp thụ ít tia → nhiều tia tới đầu thu hơn.<br>Vì vậy, nếu đầu thu nhận được tín hiệu bức xạ lớn hơn giá trị chuẩn thì chứng tỏ ít tia bị hấp thụ hơn, nghĩa là lá vật liệu đang mỏng hơn độ dày yêu cầu."}, {"question": "Nếu hệ số hấp thụ của vật liệu tăng gấp đôi nhưng độ dày không đổi thì cường độ bức xạ tới đầu thu sẽ", "choices": ["giảm gấp đôi", "giảm mạnh hơn", "không đổi", "tăng gấp đôi"], "correctIndex": 1, "explain": "<b>Câu 107: Chọn B</b><br>Ta có công thức: <span class=\"ct\">I = I<sub>0</sub>e<sup>−μx</sup></span>; Trong đó <span class=\"ct\">I<sub>0</sub></span> và <span class=\"ct\">x</span> không đổi.<br>Nếu hệ số hấp thụ tăng gấp đôi thì: <span class=\"ct\">μ&#x27; = 2μ</span><br>Khi đó cường độ mới: <span class=\"ct\">I&#x27; = I<sub>0</sub>e<sup>−2μx</sup></span><br>So với ban đầu: <span class=\"ct\">I = I<sub>0</sub>e<sup>−μx</sup></span><br>Ta thấy số mũ trong hàm mũ âm lớn hơn về độ lớn, nên giá trị của <span class=\"ct\">e<sup>−2μx</sup></span> nhỏ hơn <span class=\"ct\">e<sup>−μx</sup></span>.<br>Vì vậy: <span class=\"ct\">I&#x27; &lt; I</span>, nghĩa là cường độ bức xạ tới đầu thu giảm mạnh hơn."}, {"question": "Một nguồn có <span class=\"ct\">I<sub>0</sub> = 180</span> (<span class=\"ct\">s<sup>−1</sup></span>), <span class=\"ct\">μ = 0,3 mm<sup>−1</sup></span>. Sau khi đi qua vật liệu, đầu thu đo được <span class=\"ct\">I = 90</span> (<span class=\"ct\">s<sup>−1</sup></span>). Độ dày vật liệu gần bằng", "choices": ["<span class=\"ct\">1,5 mm</span>", "<span class=\"ct\">2,0 mm</span>", "<span class=\"ct\">2,3 mm</span>", "<span class=\"ct\">3,0 mm</span>"], "correctIndex": 2, "explain": "<b>Câu 108 chọn đáp án C </b><br><span class=\"ct\">I = I<sub>0</sub>e<sup>−μx</sup></span><img class=\"anh-de\" src=\"data/anh/l8/fa4fa5a11c09ff73.png\" alt=\"\" style=\"width:23px;height:16px;vertical-align:middle\"><span class=\"ct\">90 = 180e<sup>−0,3x</sup></span><span class=\"ct\">⇒</span>\\(x = \\dfrac{\\ln 2}{0,3} \\approx 2,3\\ \\text{mm}\\)"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Trong tự nhiên, thực vật có hoa thường sử dụng những phương pháp khác nhau để thu hút côn trùng đến thụ phấn cho chúng. Hiện tượng này tương đối phổ biến ở các loài hoa phong lan, đặc biệt là phong lan Địa Trung Hải <i>Ophrys speculum</i>. Hình thái hoa và mùi của <i>O. speculum</i> có thể hấp dẫn những cá thể đực của loài ong bắp cày <i>Campsoscolia ciliata</i>. Biểu đồ dưới đây thể hiện kết quả nghiên cứu về khả năng sinh sản của hai quần thể phong lan ở các địa điểm A và B.", "cauHoi": [{"question": "Nhận định nào sau đây là sai về số lượng quả trung bình.", "choices": ["Số lượng quả trung bình của địa điểm B là 23 quả/cây.", "Số lượng quả trung bình của địa điểm A là 1.6 quả/cây.", "Số lượng quả trung bình phần lớn phụ thuộc vào tỉ lệ đậu quả.", "Số lượng quả trung bình của địa điểm A lớn hơn địa điểm B."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b><br><i>Số lượng quả trung bình của địa điểm A là 8x20% = 1.6 quả/cây.</i><br><i>Số lượng quả trung bình của địa điểm B là 16x7% = 1.12 quả/cây.</i><br><i>Kết luận số lượng quả trung bình của địa điểm A lớn hơn B.</i>"}, {"question": "Vì sao có sự khác nhau về tỉ lệ đậu quả ở hai địa điểm A và B?", "choices": ["Tỉ lệ đậu quả phụ thuộc vào tỉ lệ ong bắp cày/m<sup>2</sup>.", "Tỉ lệ đậu quả phụ thuộc vào số lượng hoa.", "Tỉ lệ đậu quả phụ thuộc vào độ sặc sỡ của hoa.", "Tỉ lệ đậu quả phụ thuộc vào mùi hương của hoa."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b><br><i>Tỉ lệ đậu quả chỉ phụ thuộc vào tỉ lệ ong Bắp cày trên một đơn vị diện tích, vì ong Bắp cày đóng vai trò chính trong việc thụ phấn cho loài phong lan Địa Trung Hải. Tất cả những yếu tố còn lại như màu sắc, số lượng và mùi hương của hoa không được đề cập đến trong biểu đồ trên.</i>"}, {"question": "Nhận định nào sau đây là đúng khi nói về ảnh hưởng của tỉ lệ đậu quả ở phong lan <i>O.speculum</i>.", "choices": ["Mật độ ong bắp cày càng lớn, tỉ lệ đậu quả càng cao.", "Chiến lược sử dụng năng lượng của quần thể phong lan ở địa điểm A mang lại hiệu quả tốt hơn so với quần thể phong lan ở địa điểm B.", "Hình dạng và mùi hương hoa ảnh hưởng trực tiếp đến tỉ lệ thụ phấn.", "Dù cùng loài nhưng mọc ở hai địa điểm nên chúng thu hút các loài côn trùng khác nhau."], "correctIndex": 0, "explain": "<b><u>Hướng dẫn.</u></b><br><i>Dựa vào biểu đồ trên có thể thấy tỉ lệ đậu quả chỉ phụ thuộc vào tỉ lệ ong bắp cày trên một đơn vị diện tích, vì ong Bắp cày đóng vai trò chính trong việc thụ phấn cho loài phong lan Địa Trung Hải. </i><br><i>B và C sai vì dù ở hai địa điểm nhưng những cây này cùng một loài nên không có sự khác biệt về chiến lược sử dụng năng lượng cũng nhưng hình dạng và màu sắc hoa, về cơ bản hai khu vực trên vẫn cùng thuộc một khu vực địa lý, điểm khác biệt lớn nhất là sự xuất hiện của mật độ ong Bắp cày ở 2 khu vực là không giống nhau. </i><br><i>D sai, vì hình dạng và mùi hương của phong lan Địa Trung Hải Ophrys speculum được đề cập trên chỉ hấp dẫn những cá thể đực của loài Campsoscolia ciliata. </i>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Năm 2023 đã được coi là một năm nóng kỷ lục với nhân loại khi nhiệt độ trung bình cao hơn 1,45 độ C so với thời kỳ tiền công nghiệp. Theo số liệu của Liên Hợp Quốc (United Nations - UN), đến năm 2024, nhiệt độ Trái đất không có dấu hiệu giảm, mà còn có khả năng phá kỷ lục của năm 2023. Có thể nói, năm 2024 này là một năm cực kỳ khắc nghiệt và khó khăn đối với con người. Nguyên nhân chính là do hiệu ứng khí nhà kính mà con người thải ra từ các hoạt động sản xuất nông nghiệp, công nghiệp, giao thông vận tải, đặc biệt là sản xuất điện năng từ nhiên liệu hóa thạch.<br>Tính đến hết tháng 5 vừa qua, thế giới đã trải qua 12 tháng liên tiếp đạt kỷ lục nóng nhất trong lịch sử. Trong đó, mỗi tháng đều có nhiệt độ nóng hơn so với cùng kỳ của những năm trước. Sự kết hợp giữa hiệu ứng nhà kính do con người gây ra kết hợp với hiện tượng thời tiết El Nino đã khiến cho nhiều nơi trên thế giới bị bao trùm trong nắng nóng gay gắt và khắc nghiệt.<br>Tại châu Á, điển hình phải kể tới Ấn Độ và Pakistan. Trong tháng 5 vừa qua, hai quốc gia ở khu vực Nam Á này đã phải chống chọi với nhiệt độ trung bình từ 45 độ C trở lên, có nơi chạm ngưỡng 52<span class=\"ct\">°C</span> – 53 <span class=\"ct\">°C</span>. Các quốc gia khác như Việt Nam, Thái Lan, Indonesia, Malaysia, Trung Quốc cũng có nơi nóng tới 40 độ <span class=\"ct\">°C</span>.<br>Mexico, quốc gia ở khu vực Bắc Mỹ cũng phải đối mặt với nền cao ngất ngưởng, đạt mức 50 độ C là cao nhất. Trong khi đó, phía Tây châu Phi và ranh giới Sahel cũng quặn quại trong cái nóng gay gắt của vùng sa mạc. Nhiệt độ cao nhất ghi được ở khu vực này là 48,5 <span class=\"ct\">°C</span><b>.</b> Các quốc gia bị ảnh hưởng bao gồm Senegal, Guinea, Mali, Burkina, Faso, Niger, Nigeria và Chad..<br>(Nguồn: <i>Tạp chí Kinh tế và Môi trường, Thế giới đang trải qua năm 2024 đầy rẫy thiên tai, </i><br><i>chủ yếu do con người đốt nhiên liệu hóa thạch) </i>", "cauHoi": [{"question": "Quốc gia châu Á nào <b>không </b>nóng tới 40 độ C?", "choices": ["Việt Nam.", "Thái Lan.", "Trung Quốc.", "Mi-an-ma."], "correctIndex": 3, "explain": "<b>Đáp án: D </b><br><b>Giải thích: </b>“Các quốc gia khác như Việt Nam, Thái Lan, Indonesia, Malaysia, Trung Quốc cũng có nơi nóng tới 40 độ C”."}, {"question": "Nhiều nơi trên thế giới bị bao trùm trong nắng nóng gay gắt và khắc nghiệt do", "choices": ["hiện tượng thời tiết El Nino và hiệu ứng nhà kính.", "hiệu ứng nhà kính và hiện tượng thời tiết La Nina.", "hoạt động sản xuất nông nghiệp, công nghiệp.", "sản xuất điện năng từ nhiên liệu hóa thạch."], "correctIndex": 0, "explain": "<b>Đáp án: A </b><br><b>Giải thích: </b><br>“Sự kết hợp giữa hiệu ứng nhà kính do con người gây ra kết hợp với hiện tượng thời tiết El Nino đã khiến cho nhiều nơi trên thế giới bị bao trùm trong nắng nóng gay gắt và khắc nghiệt”"}, {"question": "Phát biểu nào sau đây đúng về Mexico?", "choices": ["Là quốc gia ở Nam Mỹ, nền nhiệt cao ngất ngưởng.", "Quặn quại trong cái nóng gay gắt của vùng sa mạc.", "Đối mặt với nền cao ngất ngưởng, đạt mức 40oC.", "Có nền nhiệt cao nhất cao hơn phía Tây châu Phi."], "correctIndex": 3, "explain": "<b>Đáp án: D </b><br>“Mexico, quốc gia ở khu vực Bắc Mỹ cũng phải đối mặt với nền cao ngất ngưởng, đạt mức 50 độ C là cao nhất. Trong khi đó, phía Tây châu Phi và ranh giới Sahel cũng quặn quại trong cái nóng gay gắt của vùng sa mạc. Nhiệt độ cao nhất ghi được ở khu vực này là 48,5 độ C”"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117</b><br>“Trong thế kỉ XV, triều đình tiến hành cải cách nhằm tổ chức lại bộ máy nhà nước theo hướng quy củ và tập trung hơn. Quyền lực của hoàng đế được đề cao, các chức quan được quy định rõ ràng. Đồng thời, nhà nước thiết lập cơ chế giám sát để kiểm tra hoạt động của các cơ quan nhằm hạn chế lạm quyền.<br>Bên cạnh đó, triều đình ban hành nhiều chính sách về ruộng đất để quản lí tài nguyên và thúc đẩy sản xuất nông nghiệp. Giáo dục và khoa cử được chú trọng để tuyển chọn những người có học vấn vào bộ máy quản lí.”", "cauHoi": [{"question": "Từ đoạn tư liệu, có thể nhận thấy quyền lực của hoàng đế sau cải cách", "choices": ["được tăng cường cao độ.", "bị suy giảm so với trước.", "tiếp tục bị phân tán.", "bị các đại thần lũng đoạn."], "correctIndex": 0, "explain": "<b>Câu 115. A. được tăng cường cao độ.</b><br>→ Vì đoạn tư liệu nói <b>“quyền lực của hoàng đế được đề cao”</b>."}, {"question": "Theo đoạn tư liệu, việc hạn chế tình trạng lạm quyền được thực hiện chủ yếu thông qua", "choices": ["tăng cường cơ chế giám sát.", "mở rộng lãnh thổ.", "phát triển thương nghiệp.", "ban hành luật thuế mới."], "correctIndex": 0, "explain": "<b>Câu 116. </b>A. tăng cường cơ chế giám sát.<br>→ Đoạn tư liệu nêu <b>“thiết lập cơ chế giám sát để kiểm tra hoạt động của các cơ quan nhằm hạn chế lạm quyền”</b>."}, {"question": "Việc chú trọng giáo dục và khoa cử nhằm mục đích chủ yếu là", "choices": ["tuyển chọn người có học vấn vào bộ máy quản lí.", "phát triển văn học nghệ thuật.", "mở rộng giao lưu văn hóa.", "khuyến khích sáng tác."], "correctIndex": 0, "explain": "<b>Câu 117. Chọn A. </b>tuyển chọn người có học vấn vào bộ máy quản lí.<br>→ Đoạn tư liệu nói <b>“giáo dục và khoa cử được chú trọng để tuyển chọn những người có học vấn vào bộ máy quản lí”</b>."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Điều 17 Luật An ninh quốc gia năm 2004 về Quyền và nghĩa vụ của công dân trong bảo vệ an ninh quốc gia có quy định công dân tham gia lực lượng bảo vệ an ninh quốc gia và thực hiện nhiệm vụ bảo vệ an ninh quốc gia theo quy định của pháp luật; Tố cáo hành vi xâm phạm an ninh quốc gia, hành vi lợi dụng việc thực hiện nhiệm vụ bảo vệ an ninh quốc gia xâm phạm lợi ích của Nhà nước, quyền và lợi ích hợp pháp của tổ chức, cá nhân; Phát hiện, cung cấp kịp thời thông tin, tài liệu liên quan đến hoạt động xâm phạm an ninh quốc gia cho chính quyền hoặc cơ quan chuyên trách bảo vệ an ninh quốc gia nơi gần nhất.", "cauHoi": [{"question": "Công dân thực hiện quyền bảo vệ Tổ quốc khi", "choices": ["tuân theo các quy định của Hiến pháp và pháp luật.", "đấu tranh với các hoạt động xâm phạm an ninh quốc gia.", "tố cáo các hành vi vi phạm pháp luật về bảo vệ Tổ quốc.", "tham gia xây dựng nền quốc phòng toàn dân."], "correctIndex": 2, "explain": "<b>Câu 118:</b> <b>C.</b><br>→ <b>Tố cáo hành vi vi phạm pháp luật về bảo vệ Tổ quốc</b> là <b>thực hiện quyền</b> của công dân (được pháp luật cho phép tố cáo hành vi xâm phạm an ninh quốc gia)."}, {"question": "Công dân phát hiện, cung cấp kịp thời thông tin, tài liệu liên quan đến hoạt động xâm phạm an ninh quốc gia cho chính quyền là đang thực hiện", "choices": ["quyền bình đẳng của công dân.", "nghĩa vụ của công dân trong tham gia quản lý nhà nước và xã hội.", "nghĩa vụ của công dân về khiếu nại.", "nghĩa vụ của công dân về bảo vệ Tổ quốc."], "correctIndex": 3, "explain": "<b>Câu 119: D.</b><br><b>→ Phát hiện và cung cấp thông tin về hoạt động xâm phạm an ninh quốc gia là nghĩa vụ của công dân trong bảo vệ Tổ quốc theo Luật An ninh quốc gia năm 2004.</b>"}, {"question": "Công dân tham gia lực lượng bảo vệ an ninh quốc gia và thực hiện nhiệm vụ bảo vệ an ninh quốc gia theo quy định của pháp luật là đang thực hiện", "choices": ["quyền và nghĩa vụ của công dân về khiếu nại.", "quyền của công dân trong tham gia quản lý nhà nước và xã hội.", "quyền và nghĩa vụ của công dân về bảo vệ Tổ quốc.", "quyền tự do cơ bản của công dân."], "correctIndex": 2, "explain": "<b>Câu 120: C.</b><br><b>→ Tham gia lực lượng bảo vệ an ninh quốc gia và thực hiện nhiệm vụ bảo vệ an ninh quốc gia là quyền và nghĩa vụ của công dân về bảo vệ Tổ quốc.</b>"}], "khongXaoTron": true}]};
